import javax.swing.*;import java.awt.*;
@SuppressWarnings({"unchecked","rawtypes"}) public class AllowanceSettingsPanel extends JPanel {
    private final JTextField[] values=new JTextField[7];private final JComboBox<String>[] types=new JComboBox[7];private final JLabel[] helpers=new JLabel[7];
    @SuppressWarnings("unchecked") public AllowanceSettingsPanel(){setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(7,7,7,7);c.fill=GridBagConstraints.HORIZONTAL;for(int i=0;i<CompanyPolicyStore.ALLOWANCES.length;i++){String name=CompanyPolicyStore.ALLOWANCES[i];c.gridx=0;c.gridy=i;add(new JLabel(name),c);values[i]=new JTextField(Money.text(CompanyPolicyStore.allowance(name)),12);c.gridx=1;add(values[i],c);types[i]=new JComboBox<>(new String[]{"Fixed (₹)","% of Basic Pay"});types[i].setSelectedIndex(CompanyPolicyStore.percentage(name)?1:0);helpers[i]=new JLabel();updateHelper(i);final int row=i;types[i].addActionListener(e->updateHelper(row));c.gridx=2;add(types[i],c);c.gridx=3;add(helpers[i],c);}JButton save=new JButton("Save Allowance Defaults");save.addActionListener(e->save());c.gridx=1;c.gridy=7;c.gridwidth=2;add(save,c);}
    private void updateHelper(int i){helpers[i].setText(types[i].getSelectedIndex()==1?"(% of Monthly Prorated Basic Pay)":"(Fixed Amount)");}
    private void save(){try{for(int i=0;i<values.length;i++){String name=CompanyPolicyStore.ALLOWANCES[i];CompanyPolicyStore.allowance(name,Double.parseDouble(values[i].getText()));CompanyPolicyStore.percentage(name,types[i].getSelectedIndex()==1);}for(Employee employee:new EmployeeDAO().list("")){CTCStore.Value v=CTCStore.get(employee.getId());v.hra=value("HRA",employee);v.attendance=value("Attendance Bonus",employee);v.conveyance=value("Conveyance Allowance",employee);v.performance=value("Performance Pay",employee);v.medical=value("Medical Allowance",employee);v.special=value("Special Allowance",employee);v.fixed=value("Fixed Allowance",employee);}CTCStore.flush();ActivityLogger.log("CTC Settings","ALLOWANCE DEFAULTS SAVED","Allowance defaults updated","UPDATE");JOptionPane.showMessageDialog(this,"Allowance defaults saved and applied to employee CTC records.");}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Enter valid numeric allowance values.");}}
    private double value(String name,Employee employee){double configured=CompanyPolicyStore.allowance(name);return CompanyPolicyStore.percentage(name)?configured*employee.getBasicSalary()/100:configured;}
}
